+/// The r10 finished bar, z [-80, 20], with no cross hole modelled.
+fn solid_bar() -> Mesh {
+    punched_bar::punched_bar(10.0, punched_bar::FOOT, punched_bar::TOP, &[])
+}
+
+/// The r10 bar with [`hole`] modelled in it.
+fn holed_bar() -> Mesh {
