+/// The raw stocks, each over the bar's Z span: an r20 bar and a 40 x 40
+/// box.
+fn stocks() -> [(&'static str, StockShape); 2] {
+    [("bar", StockShape::Cylinder { diameter: 40.0, height: 100.0 }), ("box", StockShape::Box { dx: 40.0, dy: 40.0, dz: 100.0 })]
+}
