+fn drill_of(h: CrossHole) -> OpParams {
+    OpParams::Drill {
+        clearance_z: Height::fixed(25.0),
+        retract_z: None,
+        top_z: Height::fixed(20.0),
+        bottom_z: None,
+        cycle: CycleChoice::Auto,
+        peck: 0.0,
+        dwell: 0.0,
+        feed: 120.0,
+        plunge_feed: 80.0,
+        holes: vec![],
+        cross: vec![h],
+    }
